def compute(vars):
    rental_revenues = vars["v1"]
    total_franchise_revenues = vars["v2"]

    if total_franchise_revenues == 0:
        return None

    ratio = rental_revenues / total_franchise_revenues
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "rental_revenues": rental_revenues,
            "total_franchise_revenues": total_franchise_revenues,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
